"""Convert plant_suitability_model.c (hex-float literals) into a TypeScript or JavaScript module.
Usage: python3 port_tree.py <model.c> <out.ts|out.mjs>"""
import re, sys
src = open(sys.argv[1]).read()
body = src[src.index('{') + 1 : src.rindex('}')]
def hexf(m):
    return repr(float.fromhex(m.group(0)))
body = re.sub(r'0x[0-9a-fA-F]+\.[0-9a-fA-F]*p[+-]?\d+', hexf, body)
body = body.replace('features[', 'f[')
out = '''// AUTO-GENERATED by tools/port_tree.py from firmware-reference/plant_suitability_model.c
// Do not edit by hand. Re-run the script if the model is retrained.
// Feature order (plant_suitability_v3_model.h):
//   [0] plant type (0 = Aloe Vera, 1 = Pothos), [1] soil %, [2] temperature C, [3] air humidity %,
//   [4] is daytime (0/1), [5] low-light minutes, [6] excessive-light minutes.
// Returns 0 = High Stress, 1 = Moderate Stress, 2 = Suitable.
/* eslint-disable */
export function predictPlantSuitability(f: readonly number[]): 0 | 1 | 2 {
''' + body.rstrip() + '\n}\n'
if sys.argv[2].endswith('.mjs'):
    out = out.replace('export function predictPlantSuitability(f: readonly number[]): 0 | 1 | 2 {', 'export function predictPlantSuitability(f) {')
open(sys.argv[2], 'w').write(out)
